(3, 'Site Editors', 'site-editors', 1, 0, NOW(), NOW()),
(4, 'Marketing Team', 'marketing', 2, 0, NOW(), NOW());

-- Group membership join table
DROP TABLE IF EXISTS `Group_Members`;
CREATE TABLE `Group_Members` (
   `ID` int NOT NULL AUTO_INCREMENT,
   `GroupID` int NOT NULL,
   `MemberID` int NOT NULL,
   PRIMARY KEY (`ID`),
   KEY `GroupID` (`GroupID`),
   KEY `MemberID` (`MemberID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `Group_Members` VALUES (1, 1, 1), (2, 2, 2), (3, 3, 2);

-- Group-Subsite access join table
DROP TABLE IF EXISTS `Group_Subsites`;
CREATE TABLE `Group_Subsites` (
   `ID` int NOT NULL AUTO_INCREMENT,
   `GroupID` int NOT NULL,
   `SubsiteID` int NOT NULL,
   PRIMARY KEY (`ID`),
   KEY `GroupID` (`GroupID`),
   KEY `SubsiteID` (`SubsiteID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Subsites
DROP TABLE IF EXISTS `Subsite`;
CREATE TABLE `Subsite` (
   `ID` int NOT NULL AUTO_INCREMENT,
   `Title` varchar(255) DEFAULT NULL,
   `Domain` varchar(255) DEFAULT NULL,
   `IsDefault` tinyint(1) DEFAULT 0,
   `Theme` varchar(100) DEFAULT 'default',
   `LastEdited` datetime DEFAULT CURRENT_TIMESTAMP,
   `Created` datetime DEFAULT CURRENT_TIMESTAMP,
   PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

