-- Schema configuration (maps class names to table names)
-- This mirrors SilverStripe's DataObject::getSchema()->tableName()
DROP TABLE IF EXISTS `_schema_config`;
CREATE TABLE `_schema_config` (
   `ID` int NOT NULL AUTO_INCREMENT,
   `ClassName` varchar(255) NOT NULL,
   `TableName` varchar(255) NOT NULL,
   `LastEdited` datetime DEFAULT CURRENT_TIMESTAMP,
   PRIMARY KEY (`ID`),
   UNIQUE KEY `ClassName` (`ClassName`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `_schema_config` VALUES
(1, 'Member', 'Member', NOW()),
(2, 'Group', 'SecurityGroup', NOW()),
(3, 'SiteTree', 'SiteTree', NOW()),
(4, 'Subsite', 'Subsite', NOW()),
(5, 'SiteConfig', 'SiteConfig', NOW());

-- Site tree (pages)
DROP TABLE IF EXISTS `SiteTree`;
CREATE TABLE `SiteTree` (
   `ID` int NOT NULL AUTO_INCREMENT,
   `ClassName` varchar(100) DEFAULT 'Page',
   `Title` varchar(255) DEFAULT NULL,
   `URLSegment` varchar(255) DEFAULT NULL,
   `Content` text,
   `ParentID` int DEFAULT 0,
   `Sort` int DEFAULT 0,
   `LastEdited` datetime DEFAULT CURRENT_TIMESTAMP,
   `Created` datetime DEFAULT CURRENT_TIMESTAMP,
   PRIMARY KEY (`ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

